SELECT count(*)
FROM iam_platform_role_assignments
WHERE identity_id = #{identityId}
  AND role_key = #{roleKey}
  AND assigned_at <= #{at}
  AND (revoked_at IS NULL OR revoked_at > #{at})

SELECT id, identity_id, role_key, assigned_at, revoked_at
FROM iam_platform_role_assignments
WHERE identity_id = #{identityId} AND role_key = #{roleKey}
  AND assigned_at <= #{at}
  AND (revoked_at IS NULL OR revoked_at > #{at})
ORDER BY assigned_at DESC LIMIT 1
